// CSD_RATIONALE_BEGIN
// Building directly on attempt 72 (best: 53.3%). The 156 wrong answers are
// semantic failures, not structural. Three dominant patterns in rollouts:
//
// (1) Wrong aggregation/ranking: "SELECT MAX(flightno)" instead of
//     JOIN + GROUP BY + ORDER BY COUNT(*) DESC LIMIT 1
// (2) Extra-column hallucination: 50+ SELECT columns instead of one
// (3) Missing WHERE/JOIN clauses: "SELECT col FROM table" (first complete parse)
//
// Architecture remains:
//   Phase 1: 5-step unconstrained preamble (model emits "SQL: <<" naturally)
//   Phase 2: Force "<<" if model didn't emit it
//   Phase 3+4: CloseSpanWithinBudget(400) — tracks LONGEST complete SQL prefix,
//              ensuring WHERE/GROUP BY/ORDER BY are included
//
// Only change from attempt 72: guidance string. Attempt 73 used 4-rule verbose
// semantic guidance and HURT (48% vs 53.3%), so this attempt keeps the
// format-focused core from attempt 72 and adds ONE targeted hint for
// ranking/aggregation queries ("most/highest" → GROUP BY + ORDER BY + LIMIT 1)
// without adding rule noise that confused the 4B model in attempt 73.
//
// Budget 400 is preserved: median 23.5 tokens/query, avg 29.27, max 249.
// Budget 400 covers all non-hallucination cases; for hallucination cases the
// longest-complete-prefix tracking in CloseSpanWithinBudget already does the
// best possible under the model's semantic limitations.
// Phase budget: 5 (preamble) + 1 (force <<) + 400 (SQL) = 406 << 900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 preamble: Loop guard includes !insideConstrainedOut, so the
//   implication is vacuously true on every iteration. The only true-flip is
//   via RenderedEndsWith("<<"), at which point we set currentConstrainedOut := []
//   and IsValidPrefix([]) holds by the method precondition. EOS break leaves
//   insideConstrainedOut unchanged (still false, implication vacuous).
//
// Phase 2 OpenConstrainedSpan: Executes only when !insideConstrainedOut.
//   Postcondition sets currentConstrainedOut := []; IsValidPrefix([]) holds
//   by the method precondition. Sets insideConstrainedOut := true.
//
// Phase 3+4 CloseSpanWithinBudget: Postcondition directly guarantees
//   (!insideConstrainedOut ==> currentConstrainedOut == []) and
//   (insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)).
//   Both closed and open-span exit paths are covered by the helper postcondition.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs 1 step and appends at most 1 token (0 on
//   EOS path via break, 1 on non-EOS path). Each iteration: steps += 1,
//   |generated| grows by <= 1. RenderedEndsWith branch only updates span
//   state, not generated length. Invariant preserved each iteration.
//
// Phase 2: OpenConstrainedSpan costs 1 step and appends exactly 1 "<<" token.
//   steps += 1, |generated| += 1. Preserved 1:1 ratio.
//
// Phase 3+4: closeBudget = min(maxSteps - steps, 400) <= maxSteps - steps.
//   CloseSpanWithinBudget postcondition: |cg| <= |generated| + closeBudget.
//   We assign steps += closeBudget, so |cg| <= |generatedPrefix| + new_steps.
//   Tokens consumed by dead-end avoidance or EOS that are not visibly appended
//   still count against closeBudget, so visible growth <= closeBudget as required.
//   cost = steps <= maxSteps: closeBudget <= maxSteps - steps_before ensures
//   steps_before + closeBudget <= maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. SELECT only the specific column(s) the question explicitly asks for — do not include extra columns. For questions asking 'which has the most/highest/largest count': use JOINs across all relevant tables, GROUP BY the target column, ORDER BY COUNT(*) DESC, LIMIT 1. The SQL must be placed between << and >>. No explanation, no markdown.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3+4 combined: Generate full SQL query and close span.
// CloseSpanWithinBudget tracks the LONGEST complete prefix seen during
// generation (not the first), so WHERE/JOIN/GROUP BY/ORDER BY clauses
// are included when the model generates them before a complete-parse point.
// Budget=400 covers 99%+ of correct Spider queries (median ~23 tokens)
// while providing room for complex multi-clause queries.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 400 {
    closeBudget := remaining;
  } else {
    closeBudget := 400;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

